import{_ as a,o,c as n,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const t="/images/admin/inventario-kardex.png",h=JSON.parse('{"title":"4. Cómo Controlar el Inventario en Bodega","description":"","frontmatter":{},"headers":[],"relativePath":"admin/inventario.md","filePath":"admin/inventario.md"}'),s={name:"admin/inventario.md"};function i(d,e,l,c,u,m){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-como-controlar-el-inventario-en-bodega" tabindex="-1">4. Cómo Controlar el Inventario en Bodega <a class="header-anchor" href="#_4-como-controlar-el-inventario-en-bodega" aria-label="Permalink to &quot;4. Cómo Controlar el Inventario en Bodega&quot;">​</a></h1><p>El módulo de <strong>Inventario</strong> (<a href="https://pyme.rsfsecure.site/admin/inventario" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/inventario</a>) te permite saber exactamente cuántas unidades tienes en almacén, registrar la llegada de nueva mercancía y hacer ajustes si algo se dañó o se extravió.</p><hr><h2 id="_4-1-historial-de-entradas-y-salidas-kardex" tabindex="-1">4.1 Historial de Entradas y Salidas (Kardex) <a class="header-anchor" href="#_4-1-historial-de-entradas-y-salidas-kardex" aria-label="Permalink to &quot;4.1 Historial de Entradas y Salidas (Kardex)&quot;">​</a></h2><p>Cada vez que se vende un artículo en la tienda, el sistema descuenta automáticamente la unidad vendida. Del mismo modo, cuando llega mercancía de los proveedores, se registra como una entrada:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Control de Inventario y Movimientos de Almacén</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/inventario</span></div><div class="screenshot-body"><img src="'+t+'" alt="Control de Inventario y Movimientos de Almacén"></div></div><hr><h2 id="_4-2-como-registrar-llegada-de-mercancia-nueva" tabindex="-1">4.2 Cómo registrar llegada de mercancía nueva <a class="header-anchor" href="#_4-2-como-registrar-llegada-de-mercancia-nueva" aria-label="Permalink to &quot;4.2 Cómo registrar llegada de mercancía nueva&quot;">​</a></h2><p>Cuando recibas un pedido de tu proveedor:</p><ol><li>Entra a <strong>Inventario</strong> y pulsa <strong>&quot;+ Registrar Entrada de Mercancía&quot;</strong>.</li><li>Busca el producto que llegó.</li><li>Escribe la cantidad de unidades que estás metiendo a la bodega (ej. <code>+50</code>).</li><li><em>(Opcional)</em> Escribe el número de factura de tu proveedor o código de compra para tus registros contables.</li><li>Haz clic en <strong>&quot;Guardar Entrada&quot;</strong>. El stock en la tienda pública se actualizará inmediatamente y los clientes ya podrán comprarlo.</li></ol><hr><h2 id="_4-3-como-hacer-un-ajuste-por-dano-o-conteo-fisico" tabindex="-1">4.3 Cómo hacer un ajuste por daño o conteo físico <a class="header-anchor" href="#_4-3-como-hacer-un-ajuste-por-dano-o-conteo-fisico" aria-label="Permalink to &quot;4.3 Cómo hacer un ajuste por daño o conteo físico&quot;">​</a></h2><p>Si durante un conteo físico descubres que falta un artículo o una caja se dañó:</p><ol><li>Haz clic en <strong>&quot;Ajuste de Inventario&quot;</strong> en el producto correspondiente.</li><li>Selecciona <strong>&quot;Ajuste por Merma / Daño&quot;</strong>.</li><li>Indica cuántas unidades vas a restar (ej. <code>-2</code>).</li><li>Escribe una nota breve explicando la razón (ej. <em>&quot;Caja rota en bodega, producto dañado&quot;</em>).</li><li>Pulsa en <strong>&quot;Guardar Ajuste&quot;</strong> para que el inventario del sistema cuadre exactamente con lo que tienes físicamente en los estantes.</li></ol>',14)])])}const v=a(s,[["render",i]]);export{h as __pageData,v as default};
